// ============================================================
// CREDO HR-Portal — Offboarding-Erinnerungs-Ergebnis auswerten
// 3-Stufen-Logik: INFO, WARNING, ESCALATION
// ============================================================

try {
  const response = $input.first().json;
  const body = response.body || response;

  const summary = {
    success: body.success || false,
    timestamp: body.timestamp || new Date().toISOString(),
    remindersProcessed: body.remindersProcessed || 0,
    errors: body.errors || 0,
    details: body.details || [],
    statusCode: response.statusCode || 200
  };

  // Nur E-Mail senden wenn Erinnerungen verschickt wurden oder Fehler auftraten
  if (summary.remindersProcessed > 0 || summary.errors > 0) {
    // Details nach Level gruppieren
    const byLevel = { INFO: [], WARNING: [], ESCALATION: [] };
    for (const d of summary.details) {
      if (byLevel[d.level]) byLevel[d.level].push(d);
    }

    const levelLabels = { INFO: 'Vorab-Info (3 Tage vor F\u00e4lligkeit)', WARNING: 'Warnung (1 Tag \u00fcberf\u00e4llig)', ESCALATION: 'Eskalation (3+ Tage \u00fcberf\u00e4llig)' };
    const levelColors = { INFO: '#009AC6', WARNING: '#FBC900', ESCALATION: '#E2001A' };

    let detailRows = '';
    for (const [level, items] of Object.entries(byLevel)) {
      for (const item of items) {
        detailRows += `<tr style="border-bottom:1px solid #eee;">`;
        detailRows += `<td style="padding:8px;font-size:13px;">${item.displayId}</td>`;
        detailRows += `<td style="padding:8px;font-size:13px;">${item.departmentName}</td>`;
        detailRows += `<td style="padding:8px;font-size:13px;"><span style="background-color:${levelColors[level]};color:#fff;padding:2px 8px;border-radius:3px;font-size:11px;">${level}</span></td>`;
        detailRows += `<td style="padding:8px;font-size:13px;">${item.overdueItems} \u00fcberf. / ${item.upcomingItems} bevorstehend</td>`;
        detailRows += `</tr>`;
      }
    }

    const htmlBody = `<div style="font-family:Calibri,Arial,sans-serif;font-size:14px;color:#2d2d2d;line-height:1.6;">
      <h2 style="color:#005d6a;">Offboarding-Erinnerungsbericht</h2>
      <p>Datum: ${new Date().toLocaleDateString('de-DE')}</p>
      <p><strong>${summary.remindersProcessed}</strong> Erinnerung(en) versendet${summary.errors > 0 ? ', <strong style="color:#E2001A;">' + summary.errors + ' Fehler</strong>' : ''}</p>
      <table style="width:100%;border-collapse:collapse;margin:15px 0;">
        <tr style="background-color:#005d6a;color:#fff;"><th style="padding:8px;text-align:left;">Vorgang</th><th style="padding:8px;text-align:left;">Abteilung</th><th style="padding:8px;text-align:left;">Level</th><th style="padding:8px;text-align:left;">Status</th></tr>
        ${detailRows}
      </table>
      <hr style="border:none;border-top:1px solid #ddd;margin:20px 0;">
      <p style="color:#999;font-size:12px;">CREDO HR-Portal \u2014 Automatischer Bericht</p>
    </div>`;

    return [{
      json: {
        sendReport: true,
        to: 'personalbuchhaltung@fes-minden.de',
        subject: `HR-Portal Offboarding: ${summary.remindersProcessed} Erinnerung(en) versendet${summary.errors > 0 ? ' (' + summary.errors + ' Fehler)' : ''}`,
        html: htmlBody,
        ...summary
      }
    }];
  }

  // Keine Erinnerungen noetig
  return [{ json: { sendReport: false, ...summary } }];

} catch (error) {
  return [{
    json: {
      sendReport: true,
      to: 'personalbuchhaltung@fes-minden.de',
      subject: 'HR-Portal: Fehler beim Offboarding-Erinnerungsversand',
      html: `<div style="font-family:Calibri,Arial,sans-serif;font-size:14px;color:#c00;">Fehler: ${error.message}</div>`,
      error: error.message
    }
  }];
}
